import os, re
root = "../../src"

def excluded_ranges(lines):
    # Brace-range exclusion for every #[cfg(test)] mod/fn block, not a
    # line-cut-to-EOF heuristic -- a file can have more than one such block,
    # and production code after an early one must stay counted.
    ranges = []
    i, n = 0, len(lines)
    while i < n:
        if re.match(r'^\s*#\[cfg\(test\)\]\s*$', lines[i]):
            j = i + 1
            while j < n and re.match(r'^\s*#\[', lines[j]):
                j += 1
            if j < n and re.search(r'\b(mod|fn)\b', lines[j]):
                depth, started, k = 0, False, j
                while k < n:
                    depth += lines[k].count('{') - lines[k].count('}')
                    if '{' in lines[k]:
                        started = True
                    if started and depth <= 0:
                        break
                    k += 1
                ranges.append((i, k))
                i = k + 1
                continue
        i += 1
    return ranges

def excluded(idx, ranges):
    return any(s <= idx <= e for s, e in ranges)

names = set()
for dirp, _, files in os.walk(root):
    for f in files:
        if not f.endswith('.rs'):
            continue
        p = os.path.join(dirp, f)
        lines = open(p).read().split("\n")
        ranges = excluded_ranges(lines)
        for i, line in enumerate(lines):
            if excluded(i, ranges):
                continue
            for m in re.finditer(r'var(?:_os)?\(\s*"(LENS_[A-Z0-9_]+)"', line):
                names.add(m.group(1))
print('distinct LENS_* env names read (non-test):', len(names))
print('\n'.join(sorted(names)))
